from lib import *
S = SS('j247')
steps = [
    step("DelayQueue 只让已到期的元素可取。放入 a(200 ms)、b(400 ms)、c(600 ms)后立刻查看:size() = 3、isEmpty() = false、peek() = a(堆顶是最早到期的,即使没到期也能看到)、poll() = null;遍历 iterator 得到 [a, c, b](堆的内部顺序,含未到期元素),remainingCapacity() = 2147483647。take() 在约 187 ms 后返回 a,再 take() 约 394 ms 时返回 b;又睡 300 ms 后 c 已到期:size() = 1、poll() = c。size() 与 isEmpty() 不区分是否到期。", t=tl(S(1)), done=lidx(S(1), '放入 a(200 ms)', 'iterator 遍历'), mark=lidx(S(1), 'take() 返回 a', '再 take() 返回 b', '又睡 300 ms'), kv=KV([['size / isEmpty / peek', '包含未到期元素'], ['poll()', '没到期返回 null'], ['take()', '阻塞到堆顶到期']], ['poll()'])),
    step("队头阻塞:A(延迟 2000 ms,序号 1)先入队,B(延迟 100 ms,序号 2)后入队,但 compareTo 按序号比较。400 ms 后 B 已到期 300 ms,poll() 返回 null,size() = 2,peek() = A,peek().getDelay = 1589 ms——B 被挡在 A 后面;poll(3 s) 等了约 1581 ms 才取到 A,随后取到 B,此时 B 比它的到期时刻晚了约 1900 ms。对照:compareTo 按到期时间比较时,400 ms 后 poll() 就是 B。compareTo 必须与 getDelay 的顺序一致。", t=tl(S(2)), done=lidx(S(2), '400 ms 后(B 已到期 300 ms)', 'poll(3 s) 返回 A'), mark=lidx(S(2), '此时 B 比它的到期时刻晚了约 1900 ms', '对照:compareTo 按到期时间比较'), b=bars([['compareTo 按序号:B 晚了', 1900, '约 1900 ms'], ['compareTo 按到期时间:B 晚了', 0, '≈ 0']], 1900, done=[0, 1]), kv=KV([['compareTo 按序号', 'B 被挡在 A 后面,晚 1900 ms'], ['compareTo 按到期时间', '400 ms 时 poll() = B']], ['compareTo 按序号'])),
    step("到期精度:10,000 个元素逐个 take()(延迟从 20 ms 起每 100 个增加 1 ms,以各自的到期时刻为预期),取到时比到期时刻晚的时间:空闲机器 p50 = 340 µs、p99 = 7890 µs、max = 7919 µs;8 个空转线程的机器 p50 = 343 µs、p99 = 4907 µs、max = 4994 µs。中位数约 0.34 ms,尾部约 5–8 ms。这里每毫秒有 100 个元素同时到期,尾部里有一部分是这一批元素被逐个取走的排队时间,不全是调度延迟。", t=tl(S(3)), done=lidx(S(3), '空闲:取到元素时比到期时间晚'), mark=lidx(S(3), '8 个空转线程'), b=bars([['空闲 p50', 340, '340 µs'], ['空闲 p99', 7890, '7890 µs'], ['8 空转线程 p50', 343, '343 µs'], ['8 空转线程 p99', 4907, '4907 µs']], 7890, done=[0, 1, 2, 3]), kv=KV([['p50', '约 0.34 ms(空闲 / 负载一样)'], ['p99', '4.9–7.9 ms(含一批元素的排队时间)']], ['p99'])),
    step("4 个消费者同时 take() 同一个 DelayQueue,只放入 1 个 100 ms 后到期的元素:500 ms 后取到元素的消费者 1 个,仍在等待的消费者 3 个。多个消费者只会有一个等待堆顶的到期时间(leader),其余无限期等待,到期元素由 leader 取走。", t=tl(S(4)), done=lidx(S(4), '500 ms 后:取到元素的消费者 1 个'), mark=lidx(S(4), '仍在等待的消费者 3 个'), kv=KV([['放入 1 个元素', '1 个消费者取到'], ['其余 3 个', '仍在等待']], ['其余 3 个'])),
    step("取消成本:remove(Object) 要线性查找。取消最晚到期的 200 个元素(取最后一次重复):队列里 1000 个元素时 DelayQueue.remove 每次约 1111 ns、10000 个约 3440 ns、100000 个约 31788 ns;对照 ScheduledThreadPoolExecutor(setRemoveOnCancelPolicy(true))的 cancel 每次约 856 ns、743 ns、39 ns。选最晚到期的元素是 remove 查找的最坏情形(它们在堆数组的末尾),也是 cancel 的最好情形,所以对比偏向 STPE;但 DelayQueue.remove 随队列增长的趋势是真实的。", t=tl(S(5)), done=lidx(S(5), '队列里 1000 个元素', '队列里 10000 个元素'), mark=lidx(S(5), '队列里 100000 个元素'), b=bars([['DelayQueue.remove(1000)', 1111, '1111 ns'], ['DelayQueue.remove(10000)', 3440, '3440 ns'], ['DelayQueue.remove(100000)', 31788, '31788 ns'], ['STPE cancel(100000)', 39, '39 ns']], 31788, done=[0, 1, 2, 3]), kv=KV([['DelayQueue.remove', '1 千 → 10 万个元素:1.1 µs → 31.8 µs'], ['STPE cancel', '不随长度增长(最好情形 39 ns)']], ['DelayQueue.remove'])),
]
A = mkartj('j247', 247, 'Java,并发,DelayQueue,Delayed,定时,BlockingQueue,真实验证,动画演示',
    '实测 DelayQueue:poll 只返回已到期元素而 size / isEmpty / peek 包含未到期的;compareTo 与到期时间不一致时 B 被挡在 A 后面晚了约 1900 ms;到期后取到的延迟 p50 约 0.34 ms、p99 约 5–8 ms;4 个消费者只有 1 个取到元素;remove(Object) 随长度线性增长(10 万个约 31788 ns)。',
    'DelayQueue 是“到期才可取”的优先级队列,常被用来写本地缓存过期和定时任务。这篇量出它的语义细节、compareTo 写错时的队头阻塞、到期精度、多消费者行为和取消成本。',
    [('1900 ms', 'compareTo 与到期顺序不一致时,B 比到期时刻晚被取到的时间'), ('0.34 ms', '取到元素时比到期时刻晚的中位数(p99 约 5–8 ms)'), ('31788 ns', '队列里 10 万个元素时 DelayQueue.remove 的单次成本(1000 个时约 1111 ns)')],
    [('已到期才可取', None), ('队头阻塞', None), ('到期精度', None), ('多个消费者', None), ('取消成本', None)],
    steps, [ENV_J + '。JDK 21.0.12;10 个逻辑 CPU;到期精度用 System.nanoTime 做时间源,元素按每毫秒 100 个批量到期,尾部延迟含批内排队', '没有验证:getDelay 用 System.currentTimeMillis 时系统时钟被调整的行为、DelayQueue 作为本地缓存过期队列的内存与回收、虚拟线程消费者、cancel 位置不同(随机、最早到期)时的 remove 成本'], 'DelayQueue')
